compile.workshop:
variables {
    global:
        0: g
        1: h
}

rule ("x") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
        "pass"
        disabled Abort;
        //lbl_0:
        Set Global Variable(g, 2);
    }
}

rule ("y") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
        Skip If(Compare(Global.h, ==, Null), 1);
        Set Global Variable(g, 5);
        //lbl_1:
        Set Global Variable(g, 2);
    }
}

rule ("z") {
    event {
        Ongoing - Global;
    }
    actions {
        Set Global Variable(g, 1);
        Skip If(Compare(Global.h, ==, Null), 2);
        Set Global Variable(g, 5);
        Set Global Variable(g, 6);
        //lbl_2:
    }
}

